const app = document.getElementById('app');
const modalRoot = document.getElementById('modal-root');
const icons = {chat:'M4 5h16v11H8l-4 3z',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-6-13-4 16',folder:'M3 6h7l2 2h9v11H3z',search:'M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 4 4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-5v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4',panel:'M3 4h18v16H3zM8 4v16',right:'M3 4h18v16H3zM16 4v16',plus:'M12 4v16M4 12h16',chevron:'m9 6 6 6-6 6',down:'m6 9 6 6 6-6',file:'M6 3h8l4 4v14H6zM14 3v5h4',send:'M5 12h14m-5-5 5 5-5 5',stop:'M7 7h10v10H7z',check:'m5 12 4 4L19 6',x:'M6 6l12 12M18 6 6 18',terminal:'m4 6 5 5-5 5m7 2h9',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',warning:'M12 3 2 20h20L12 3Zm0 6v5m0 3v.1',save:'M5 4h12l2 2v14H5zM8 4v6h8V4M8 20v-7h8v7'};
const icon=(n,s=16)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const initialCode=`import { useState } from 'react';\n\nexport function TaskPanel() {\n  const [status, setStatus] = useState('ready');\n\n  return (\n    <section className="task-panel">\n      <h2>Работа агента</h2>\n      <p>Проверяйте изменения перед применением.</p>\n      <button onClick={() => setStatus('running')}>\n        Начать проверку\n      </button>\n    </section>\n  );\n}\n`;
let state={mode:'ide',scenario:'ready',sidebar:true,context:true,drawer:false,search:'',selected:'TaskPanel.tsx',draft:initialCode,saved:initialCode,tool:'',inspector:'plan',decision:'pending',sideView:'files',projectQuery:'',memory:'Сохранять текущую компоновку и показывать реальные результаты проверок.',settingsTab:'layout',detailsOpen:false,model:'Neutral Demo',settingsQuery:'',messages:[],prompt:'',emptyHistory:false,running:false,settings:false,side:'right',notice:'',session:'Подготовить панель задач'};
const layoutDefaults={sidebar:234,agent:400,context:258,details:400,settings:230};
let layout={...layoutDefaults};
try{const stored=JSON.parse(localStorage.getItem('neutral-prototype-layout-v1')||'{}');for(const key of Object.keys(layout))if(Number.isFinite(stored[key]))layout[key]=stored[key];}catch{}
const limits={sidebar:[180,400],agent:[300,700],context:[200,500],details:[300,700],settings:[180,340]};
function effectiveLayout(){
 const w=innerWidth;const x={...layout};
 for(const key of Object.keys(x))x[key]=Math.min(limits[key][1],Math.max(limits[key][0],x[key]));
 const rightKey=state.mode==='ide'?'agent':'context';
 x.sidebar=Math.min(x.sidebar,w-(state.context?limits[rightKey][0]:0)-340);
 x[rightKey]=Math.min(x[rightKey],w-(state.sidebar?x.sidebar:0)-340);
 x.details=Math.min(x.details,w-(state.sidebar?x.sidebar:0)-220);
 return x;
}
function applyLayout(){const x=effectiveLayout();for(const [key,value] of Object.entries(x))document.documentElement.style.setProperty('--width-'+key,value+'px');document.querySelectorAll('[data-resize]').forEach(n=>{n.setAttribute('aria-valuenow',Math.round(x[n.dataset.resize]));});}
function persistLayout(){try{localStorage.setItem('neutral-prototype-layout-v1',JSON.stringify(layout));}catch{}}
function resizeHandle(key,edge='right'){return `<div class="resize-handle edge-${edge}" data-resize="${key}" data-edge="${edge}" role="separator" aria-orientation="vertical" aria-label="Ширина: ${{sidebar:'история и файлы',agent:'панель агента',context:'контекст',details:'подробности задачи',settings:'разделы настроек'}[key]}" aria-valuemin="${limits[key][0]}" aria-valuemax="${limits[key][1]}" tabindex="0" title="Потяните границу · стрелки меняют ширину · двойной щелчок сбрасывает"></div>`;}
function bindResizers(){
 document.querySelectorAll('[data-resize]').forEach(n=>{
  const key=n.dataset.resize;const sign=n.dataset.edge==='left'?-1:1;
  n.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();n.focus();const startX=e.clientX,start=effectiveLayout()[key];n.setPointerCapture(e.pointerId);document.body.classList.add('resizing');
   const move=ev=>{const effective=effectiveLayout();let max=limits[key][1];if(key==='sidebar')max=Math.min(max,innerWidth-(state.context?limits[state.mode==='ide'?'agent':'context'][0]:0)-340);if(key==='agent'||key==='context')max=Math.min(max,innerWidth-(state.sidebar?effective.sidebar:0)-340);layout[key]=Math.max(limits[key][0],Math.min(max,start+(ev.clientX-startX)*sign));applyLayout();};
   const stop=()=>{n.removeEventListener('pointermove',move);n.removeEventListener('pointerup',stop);n.removeEventListener('pointercancel',stop);n.removeEventListener('lostpointercapture',stop);document.body.classList.remove('resizing');persistLayout();};
   n.addEventListener('pointermove',move);n.addEventListener('pointerup',stop);n.addEventListener('pointercancel',stop);n.addEventListener('lostpointercapture',stop);
  });
  n.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();let value=e.key==='Home'?limits[key][0]:e.key==='End'?limits[key][1]:effectiveLayout()[key]+(e.key==='ArrowRight'?16:-16)*sign;layout[key]=Math.max(limits[key][0],Math.min(limits[key][1],value));applyLayout();persistLayout();});
  n.addEventListener('dblclick',()=>{layout[key]=layoutDefaults[key];applyLayout();persistLayout();});
 });applyLayout();
}
window.addEventListener('resize',applyLayout);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,ic,extra='')=>`<button type="button" data-action="${action}" ${extra}>${ic?icon(ic):''}<span>${label}</span></button>`;
function header(){return `<header class="topbar"><div class="brand"><span class="brandmark">N</span><strong>Neutral</strong><span class="demo-label">ПРОТОТИП</span></div><div class="mode-switch" role="tablist" aria-label="Режим"><button role="tab" aria-selected="${state.mode==='ide'}" data-action="mode-ide">${icon('code')} IDE</button><button role="tab" aria-selected="${state.mode==='chat'}" data-action="mode-chat">${icon('chat')} Chat</button></div><div class="top-spacer"></div><button class="lola-open" data-action="open-lola">Лола ${icon('chat',14)}</button><span class="demo-note">Демонстрационные данные · без подключения к агенту</span><button class="icon-button" title="Показать или скрыть историю и файлы" aria-label="Показать или скрыть боковую панель" data-action="toggle-sidebar">${icon('panel')}</button><button class="icon-button" title="Показать или скрыть контекст" aria-label="Показать или скрыть контекст" data-action="toggle-context">${icon('right')}</button><button class="icon-button" aria-label="Настройки прототипа" title="Настройки прототипа" data-action="settings">${icon('settings')}</button></header>`}
const sessions=['Подготовить панель задач','Разобраться с проектом','План проверки интерфейса'];
function sidebar(){if(!state.sidebar)return '';return `<aside class="sidebar" aria-label="Боковая панель">${resizeHandle('sidebar')}${reviewProject()}<div class="side-tabs"><span class="side-tab active">${state.mode==='ide'?'ФАЙЛЫ ПРОЕКТА':'РАЗГОВОРЫ'}</span></div>${state.mode==='ide'?`<div class="sidebar-views" role="group" aria-label="Области проекта">${[['files','Файлы'],['project-search','Поиск'],['memory','Память']].map(([id,label])=>`<button data-side-view="${id}" aria-pressed="${state.sideView===id}" class="${state.sideView===id?'selected':''}">${label}</button>`).join('')}</div>${sideContent()}`:reviewHistory()}<div class="sidebar-foot">${icon('folder',14)} Демо-проект <span>локально</span></div></aside>`}
function sideContent(){
 if(state.sideView==='project-search')return reviewSearch();
 if(state.sideView==='memory')return reviewMemory();
 if(state.sideView==='project-search'){const q=state.projectQuery.trim().toLowerCase();const found=['TaskPanel.tsx','styles.css','README.md'].filter(f=>!q||f.toLowerCase().includes(q));return `<div class="project-search"><label for="project-query">Поиск в демо-проекте</label><input id="project-query" value="${esc(state.projectQuery)}" placeholder="Имя файла…">${found.length?found.map(f=>`<button class="tree-file" data-file="${f}">${icon('file',14)} ${f}</button>`).join(''):'<p>Нет совпадений</p>'}<small>Поиск только по трём демо-файлам</small></div>`}
 if(state.sideView==='memory')return `<div class="memory-demo"><label for="memory-note">Заметка проекта · демо</label><textarea id="memory-note" rows="4">${esc(state.memory)}</textarea><small>Черновик хранится до закрытия прототипа</small></div>`;
 return `<div class="tree"><div class="tree-root">${icon('down',14)} ${icon('folder',15)} <strong>neutral-demo</strong></div><div class="tree-section">${icon('down',14)} ${icon('folder',15)} src</div>${['TaskPanel.tsx','styles.css','README.md'].map(f=>`<button class="tree-file ${state.selected===f?'selected':''}" data-file="${f}">${icon('file',15)} ${f}</button>`).join('')}</div>`;
}
function toolList(){return `<div class="activity-head"><span>ХОД РАБОТЫ</span><span>3 действия</span></div><div class="activity">${[['read','Чтение файлов','src/TaskPanel.tsx','check'],['search','Поиск в проекте','Найдено 3 совпадения','check'],['test','Проверка интерфейса',state.running?'Выполняется':'Ожидает запуска','terminal']].map(([id,title,detail,ic])=>`<button class="tool-row" data-tool="${id}" aria-expanded="${state.tool===id}"><span class="tool-icon">${icon(ic,14)}</span><span>${title}<small>${detail}</small></span>${icon('chevron',14)}</button><div class="tool-detail" data-tool-detail="${id}" ${state.tool===id?'':'hidden'}><span>Демонстрация результата</span><code>${id==='read'?'src/TaskPanel.tsx · строки 1–14':id==='search'?'task-panel · 3 совпадения':'Локальный сценарий прототипа'}</code></div>`).join('')}</div>`}
const inspectorTabs=[['plan','План'],['checks','Проверки'],['changes','Изменения'],['context','Контекст'],['subagents','Субагенты'],['history','Запуски']];
function taskInspector(){
 const view=state.inspector;
 const tabs=inspectorTabs.map(([id,label])=>`<button data-inspect="${id}" class="${view===id?'selected':''}" aria-pressed="${view===id}">${label}</button>`).join('');
 const panels={
  activity:toolList(),
  plan:`<div class="detail-card"><div class="detail-head"><strong>План задачи</strong><span>1 / 3 готово</span></div><div class="step done"><b>01</b><span>Изучить структуру проекта</span><small>Готово</small></div><div class="step"><b>02</b><span>Подготовить изменение</span><small>В работе</small></div><div class="step"><b>03</b><span>Проверить результат</span><small>Ожидает</small></div><p>Критерий: состояния задачи читаются и доступны с клавиатуры.</p></div>`,
  checks:`<div class="detail-card"><div class="detail-head"><strong>Проверки и критерии</strong><span>Демо</span></div><div class="step done"><b>✓</b><span>Проверка структуры</span><small>Пройдено</small></div><div class="step"><b>·</b><span>Сборка интерфейса</span><small>Не запускалась</small></div><p>Статус указывает только на демонстрационный пример; реальные проверки не выполнялись.</p></div>`,
  changes:`<div class="detail-card review-card"><div class="detail-head"><strong>Предложенное изменение</strong><span>${state.decision==='pending'?'Ждёт решения':state.decision==='apply'?'Демо принято':state.decision==='reject'?'Демо отклонено':'Отложено'}</span></div><p>src/TaskPanel.tsx · демонстрационный diff</p><pre class="diff"><span>- &lt;h2&gt;Статус&lt;/h2&gt;</span>
<span>+ &lt;h2&gt;Работа агента&lt;/h2&gt;</span></pre><p>Решение меняет только состояние прототипа; файл на диске не изменится.</p>${state.decision==='pending'?`<div class="review-actions"><button data-decision="later">Позже</button><button data-decision="reject">Отклонить</button><button data-decision="apply">Принять демо</button></div>`:`<button class="text-button" data-decision="pending">Вернуть демо на проверку</button>`}</div>`,
  context:`<div class="detail-card"><div class="detail-head"><strong>Контекст задачи</strong><span>Демо · 42%</span></div><div class="meter"><span></span></div><p>Сообщения, выбранные файлы и результаты инструментов. Перед отправкой исходников внешней модели в основном приложении необходимо подтверждение.</p><div class="detail-line">src/TaskPanel.tsx <span>выбран</span></div><div class="detail-line">История разговора <span>доступна</span></div></div>`,
  subagents:`<div class="detail-card"><div class="detail-head"><strong>Дочерние исследования</strong><span>1 демо</span></div><div class="step"><b>↳</b><span>Аудит интерфейса</span><small>Только чтение</small></div><p>Показаны задача, статус и границы доступа. Реальный субагент здесь не запускается.</p></div>`,
  history:`<div class="detail-card"><div class="detail-head"><strong>История запусков</strong><span>Демо</span></div><div class="step done"><b>✓</b><span>Проверка структуры</span><small>Результат получен</small></div><div class="step"><b>↻</b><span>Подготовка изменений</span><small>Можно продолжить</small></div><p>В действующем Neutral здесь доступны история, восстановление и проверка результатов.</p></div>`
 };
 return `<div class="task-summary"><div class="task-summary-top"><div><span class="summary-kicker">АКТИВНАЯ ЗАДАЧА <span> / DEMO</span></span><strong>Подготовить панель задач</strong></div></div><div class="summary-meta"><span><i></i>${state.running?'В работе':'Демонстрация'}</span><span>01 / 03 этапа</span><span>42% контекст</span></div></div><div class="inspector-tabs" role="group" aria-label="Подробности задачи">${tabs}</div>${panels[view]}${reviewTaskExtra()}`;
}
function composer(){return `<div class="composer-wrap"><div class="composer"><textarea id="prompt" aria-label="Сообщение агенту" placeholder="Опишите задачу…" rows="2">${esc(state.prompt)}</textarea><div class="review-composer-tools">${reviewButton("attach",review.attached?"✓ TaskPanel.tsx":"+ Контекст",`aria-pressed="${review.attached}"`)}${reviewButton("task-options","Критерии задачи")}</div><div class="composer-bottom"><label class="model-picker"><span>Модель</span><select id="model-select" aria-label="Выбрать модель демонстрации">${['Neutral Demo','Local Demo','API Demo'].map(m=>`<option ${state.model===m?'selected':''}>${m}</option>`).join('')}</select></label>${state.running?btn('stop','Остановить','stop','class="send"'):btn('send','Отправить','send','class="send"')}</div></div><div class="composer-hint">Данные и ответы показаны только в прототипе</div></div>`}
function chatBody(compact=false){const empty=state.scenario==='empty';return `<div class="conversation ${compact?'compact':''}"><div class="conversation-title"><div><h1>${state.mode==='ide'?'Задача агента':esc(state.session)}</h1></div>${state.mode==='ide'?`<button class="task-details-button history-toggle" data-action="toggle-history" aria-expanded="${review.historyOpen}" aria-controls="agent-history">Разговоры ${icon('clock',14)}</button>`:''}<button class="task-details-button" data-action="toggle-details" aria-expanded="${state.detailsOpen}">Подробности ${icon('right',14)}</button></div><div class="message-scroll">${empty?'<div class="empty-state"><h2>Начните разговор</h2><p>Опишите задачу — здесь появятся сообщения и действия агента.</p></div>':`<div class="message user-message"><div class="message-meta">ВЫ <span>10:24</span>${reviewButton('copy-message','Копировать','class="review-copy"')}</div><p>${state.mode==='ide'?'Проверь панель задач и предложи улучшения интерфейса.':'Помоги разобраться в структуре проекта и покажи ход работы.'}</p></div><div class="message assistant-message"><div class="message-meta"><span class="assistant-mark">N</span> NEUTRAL <span>10:24</span>${reviewButton('copy-message','Копировать','class="review-copy"')}</div><p>Изучу структуру проекта и проверю, как отображаются состояния задачи.</p>${toolList()}<p>Нашёл компонент панели. В демонстрации можно открыть файл, посмотреть действия и изменить расположение областей.</p>${state.scenario==='rich'?reviewRichMessage():''}</div>${state.messages.map(m=>`<div class="message user-message"><div class="message-meta">ВЫ · ДЕМО ${reviewButton('copy-message','Копировать','class="review-copy"')}</div><p>${esc(m)}</p></div>`).join('')}${state.notice?`<div class="notice" role="status">${esc(state.notice)}</div>`:''}${state.scenario==='error'?`<div class="error-card" role="alert">${icon('warning')}<div><strong>Демонстрационная ошибка</strong><p>Не удалось получить ответ. Это пример ошибки подключения.</p><div class="error-actions"><button data-action="retry-demo">Повторить демо</button><button data-action="dismiss-error">Скрыть</button></div></div></div>`:''}`}</div><button class="review-latest" data-review="latest">К последнему сообщению ↓</button>${composer()}</div>`}
function editor(){const code=reviewCode();if(!review.tabs.includes(state.selected))review.tabs.push(state.selected);return `<section class="editor" aria-label="Редактор файлов"><div class="editor-tabs"><div class="review-file-tabs">${review.tabs.map(f=>`<div class="editor-tab ${f===state.selected?'active':''}"><button data-tab-file="${f}">${icon('file',14)} ${esc(f)}${f==='TaskPanel.tsx'&&state.draft!==state.saved?' •':''}</button><button data-close-file="${f}" aria-label="Закрыть ${f}">${icon('x',12)}</button></div>`).join('')}</div><button class="icon-button" data-action="save-file" title="Сохранить демо-черновик" aria-label="Сохранить демо-черновик" ${state.draft===state.saved||state.selected!=='TaskPanel.tsx'?'disabled':''}>${icon('save',15)}</button></div><div class="breadcrumbs">neutral-demo <span>›</span> src <span>›</span> ${esc(state.selected)}</div>${reviewEditorBar()}<div class="code-area"><div class="line-numbers" aria-hidden="true">${Array.from({length:Math.max(16,code.split('\n').length)},(_,i)=>i+1).join('<br>')}</div><textarea id="code-input" spellcheck="false" aria-label="Содержимое демонстрационного файла" ${state.selected!=='TaskPanel.tsx'?'readonly':''}>${esc(code)}</textarea></div>${reviewOutput()}<div class="editor-foot"><span>${state.draft!==state.saved?'Есть несохранённые изменения':'Демо-файл'}</span><span>Строка ${review.line} · UTF-8</span></div></section>`}
