const settingsPages=[['layout','Раскладка'],['model','Модель'],['tools','Инструменты'],['access','Доступ'],['voice','Голос и Лола'],['storage','История и копии'],['runtime','Локальный запуск'],['connections','ПК и Telegram'],['ide','Возможности IDE']];
function settings(){
 const content={
  runtime:`<div class="settings-info"><h3>Локальный запуск</h3><p>Существующий runtime Neutral: путь к серверу, выбор модели и передача адреса подключения. Управление процессом подключается на этапе интеграции.</p><p>В прототипе runtime не запускается.</p></div>`,
  connections:`<div class="settings-info"><h3>Компьютер и Telegram</h3><p>Desktop tools, список приложений, подключение бота и защищённое хранение токена. Здесь должны сохраниться действующие настройки и подтверждения.</p><p>Раздел показывает размещение функций; доступы не изменяются.</p></div>`,
  ide:`<div class="settings-info"><h3>Возможности IDE</h3><p>Исследование, диагностика LSP, рабочие копии Git, Docker и границы доступа к рабочим папкам.</p><p>В прототипе нет запуска этих сервисов.</p></div>`,
  layout:`<div class="setting-row"><div><strong>Боковая панель</strong><small>Файлы и история разговоров</small></div><button data-action="toggle-sidebar">${state.sidebar?'Скрыть':'Показать'}</button></div><div class="setting-row"><div><strong>Панель агента / контекста</strong><small>Правая область IDE или область контекста Chat</small></div><button data-action="toggle-context">${state.context?'Скрыть':'Показать'}</button></div><div class="setting-row"><div><strong>Расположение контекста</strong><small>Применяется к режиму Chat</small></div><button data-action="swap-context">${state.side==='right'?'Справа':'Слева'}</button></div>`,
  model:`<div class="settings-info"><h3>Подключение модели</h3><p>Здесь в основном приложении находятся провайдер, URL, модель, проверка соединения и профили.</p><div class="example-row"><span>Провайдер</span><strong>Локальный / внешний API</strong></div><div class="example-row"><span>Управление контекстом</span><strong>Автоматически или вручную</strong></div><p>Значения показаны как пример: настройки модели не подключены.</p></div>`,
  tools:`<div class="settings-info"><h3>Возможности агента</h3><p>Наборы инструментов, навыки, плагины и MCP-серверы. Профили субагентов и дополнительные возможности IDE настраиваются здесь же или в соответствующих разделах.</p><div class="example-row"><span>Инструменты и навыки</span><strong>Выбор и редактирование</strong></div><div class="example-row"><span>MCP / субагенты</span><strong>Подключение и профили</strong></div><p>Демонстрация структуры раздела; изменения не выполняются.</p></div>`,
  access:`<div class="settings-info"><h3>Доступ к проекту</h3><p>Границы доступа к рабочим папкам, изоляция, запросы перед записью файлов, выполнением команд, MCP и передачей исходников.</p><div class="example-row"><span>Изменения файлов</span><strong>Просмотр diff и решение</strong></div><div class="example-row"><span>Запуск команд</span><strong>Просмотр и подтверждение</strong></div><p>Демо не изменяет реальные разрешения.</p></div>`,
  voice:`<div class="settings-info"><h3>Голос и Лола</h3><p>Микрофон, распознавание и синтез речи, голос, wake phrase и отдельное окно Лолы остаются функциями основного приложения.</p><div class="example-row"><span>Ввод и озвучивание</span><strong>Настройки голоса</strong></div><div class="example-row"><span>Лола</span><strong>Отдельный режим и окно</strong></div><p>Микрофон и голос в этом прототипе не используются.</p></div>`,
  storage:`<div class="settings-info"><h3>История и копии</h3><p>История разговоров, архив, экспорт и резервные копии; управление данными должно оставаться доступным в основном приложении.</p><div class="example-row"><span>Разговоры</span><strong>Поиск, архив и экспорт</strong></div><div class="example-row"><span>Данные</span><strong>Хранение и копии</strong></div><p>Реальные данные не подключены и не изменяются.</p></div>`
 };
 return `<div class="modal-backdrop"><section class="dialog settings-dialog" role="dialog" aria-modal="true" aria-labelledby="settings-title"><div class="dialog-head"><div><span class="eyebrow">ПРОТОТИП · ДЕМОНСТРАЦИЯ РАЗДЕЛОВ</span><h2 id="settings-title" tabindex="-1">Настройки Neutral</h2></div><button class="icon-button" aria-label="Закрыть настройки" data-action="close-settings">${icon('x')}</button></div><p>Демо-формы для оценки интерфейса. Модель, голос и сервисы не подключены.</p><div class="settings-body"><nav class="settings-nav" aria-label="Разделы настроек">${resizeHandle('settings')}<label class="settings-search"><input id="settings-query" aria-label="Поиск раздела настроек" placeholder="Поиск настроек…" value="${esc(state.settingsQuery)}"></label>${settingsPages.filter(([id,label])=>label.toLowerCase().includes(state.settingsQuery.toLowerCase())).map(([id,label])=>`<button data-settings-tab="${id}" class="${state.settingsTab===id?'selected':''}" aria-pressed="${state.settingsTab===id}">${label}</button>`).join('')}${settingsPages.some(([,label])=>label.toLowerCase().includes(state.settingsQuery.toLowerCase()))?'':'<p class="settings-no-results">Разделы не найдены</p>'}</nav><div class="settings-content">${reviewSettingsContent(state.settingsTab)||content[state.settingsTab]}</div></div><div class="dialog-foot"><button class="primary" data-action="close-settings">Готово</button></div></section></div>`;
}

function render(){app.innerHTML=`<div class="shell" ${state.settings||review.dialog?'inert':''}>${header()}<div class="body-layout ${state.mode} ${state.side==='left'?'context-left':''}">${sidebar()}<main class="workspace">${state.mode==='ide'?`${editor()}${state.context?`<div class="agent-panel">${resizeHandle('agent','left')}${chatBody(true)}</div>`:''}`:chatBody()}${state.detailsOpen?`<aside class="task-drawer" aria-label="Подробности задачи">${resizeHandle(state.mode==='ide'?'agent':'details','left')}<header><strong>Задача</strong><button class="icon-button" data-action="toggle-details" aria-label="Закрыть подробности">${icon('x')}</button></header>${taskInspector()}</aside>`:''}${review.historyOpen&&state.mode==='ide'?reviewHistoryDrawer():''}</main>${state.mode==='chat'?context():''}</div><footer class="statusbar"><span><i></i> Демо-режим</span><span>${state.mode==='ide'?'IDE':'Chat'} · Данные не отправляются</span><button data-action="scenarios">Состояния для проверки ${icon('down',12)}</button></footer>${state.drawer?`<div class="scenario-menu"><div>ДЕМО-СОСТОЯНИЯ</div>${[['ready','Разговор'],['working','Агент работает'],['tools','Вызовы инструментов'],['changes','Проверка изменений'],['file','Открытый файл'],['settings','Настройки'],['approval','Запрос подтверждения'],['recovery','Восстановление'],['queue','Очередь задач'],['rich','Код и таблицы'],['error','Ошибка'],['empty','Пустой список']].map(([k,v])=>`<button data-scenario="${k}">${v}</button>`).join('')}</div>`:''}</div>`;modalRoot.innerHTML=(state.settings?settings():'')+reviewDialog();bind()}
function bind(){bindResizers();reviewBind();document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('[data-file]').forEach(b=>b.addEventListener('click',()=>{state.selected=b.dataset.file;state.mode='ide';review.tabs=[...new Set([...review.tabs,state.selected])];render()}));document.querySelectorAll('[data-session]').forEach(b=>b.addEventListener('click',()=>{state.session=b.dataset.session;state.scenario='ready';state.messages=[];render()}));document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>{const tool=b.dataset.tool;state.tool=state.tool===tool?'':tool;render();document.querySelector('[data-tool='+tool+']').focus()}));document.querySelectorAll('[data-side-view]').forEach(b=>b.addEventListener('click',()=>{state.sideView=b.dataset.sideView;render();document.querySelector('[data-side-view='+state.sideView+']').focus()}));document.querySelectorAll('[data-settings-tab]').forEach(b=>b.addEventListener('click',()=>{state.settingsTab=b.dataset.settingsTab;render();document.querySelector('[data-settings-tab='+state.settingsTab+']').focus()}));document.querySelectorAll('[data-inspect]').forEach(b=>b.addEventListener('click',()=>{state.inspector=b.dataset.inspect;render();document.querySelector('[data-inspect='+state.inspector+']').focus()}));document.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>{state.decision=b.dataset.decision;render()}));document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>setScenario(b.dataset.scenario)));const modelSelect=document.getElementById('model-select');if(modelSelect)modelSelect.addEventListener('change',e=>{state.model=e.target.value});const settingsSearch=document.getElementById('settings-query');if(settingsSearch)settingsSearch.addEventListener('input',e=>{state.settingsQuery=e.target.value;const at=e.target.selectionStart;render();const input=document.getElementById('settings-query');input.focus();input.setSelectionRange(at,at)});const projectQuery=document.getElementById('project-query');if(projectQuery)projectQuery.addEventListener('input',e=>{state.projectQuery=e.target.value;let pos=e.target.selectionStart;render();const el=document.getElementById('project-query');el.focus();el.setSelectionRange(pos,pos)});const memory=document.getElementById('memory-note');if(memory)memory.addEventListener('input',e=>{state.memory=e.target.value});const search=document.getElementById('conversation-search');if(search)search.addEventListener('input',e=>{state.search=e.target.value;let pos=e.target.selectionStart;render();let el=document.getElementById('conversation-search');el.focus();el.setSelectionRange(pos,pos)});const code=document.getElementById('code-input');if(code&&state.selected==='TaskPanel.tsx')code.addEventListener('input',e=>{state.draft=e.target.value;document.querySelector('[data-action=save-file]').disabled=state.draft===state.saved;document.querySelector('.editor-foot span').textContent=state.draft===state.saved?'Демо-файл':'Есть несохранённые изменения'});const prompt=document.getElementById('prompt');if(prompt)prompt.addEventListener('input',e=>{state.prompt=e.target.value});if(prompt)prompt.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();action('send')}})}
function action(a){if(a==='save-file'&&state.draft!==state.saved){reviewOpenDialog('save','Просмотр сохранения');return;}if(a==='toggle-history'){review.historyOpen=!review.historyOpen;state.detailsOpen=false;state.context=true;review.menu='';render();document.querySelector(review.historyOpen?'#conversation-search':'.history-toggle')?.focus();return;}if(a==='toggle-details')review.historyOpen=false;if(a.startsWith('mode-')){review.historyOpen=false;}if(a==='new'){reviewAction('new-chat');return;}if(state.settings&&!['toggle-sidebar','toggle-context','swap-context','close-settings'].includes(a))return;if(a==='toggle-details'){state.detailsOpen=!state.detailsOpen;render();document.querySelector(state.detailsOpen?'.task-drawer header button':'.task-details-button')?.focus();return;}if(a==='retry-demo'){state.scenario='ready';state.running=true;state.notice='Повторный локальный сценарий запущен.';}if(a==='dismiss-error'){state.scenario='ready';}if(a==='open-lola'){window.neutralPrototype?.openLola();return;}if(a==='mode-ide')state.mode='ide';if(a==='mode-chat')state.mode='chat';if(a==='toggle-sidebar')state.sidebar=!state.sidebar;if(a==='toggle-context')state.context=!state.context;if(a==='swap-context')state.side=state.side==='right'?'left':'right';if(a==='settings'){state.settings=true;render();document.getElementById('settings-title').focus();return}if(a==='close-settings'){state.settings=false;render();document.querySelector('[data-action=settings]').focus();return}if(a==='scenarios')state.drawer=!state.drawer;if(a==='new'){state.prompt='';state.emptyHistory=false;state.mode='chat';state.scenario='empty';state.session='Новый разговор';state.messages=[];state.running=false}if(a==='save-file'){state.saved=state.draft;state.notice='Демо-черновик сохранён в памяти прототипа.'}if(a==='send'){const input=document.getElementById('prompt');if(!input||!input.value.trim())return;state.messages.push(input.value.trim());state.prompt='';state.scenario='ready';state.running=true;state.notice='Демонстрационная задача запущена. Сообщение никуда не отправлено.'}if(a==='stop'){state.running=false;state.notice='Сценарий остановлен.'}render();if(state.settings){const control=document.querySelector('.dialog [data-action='+a+']');if(control)control.focus()}}
function setScenario(s){review.historyOpen=false;review.menu='';review.dialog='';if(s==='approval'){review.approvalResult='';review.dialog='approval';review.dialogTitle='Запрос решения';}if(s==='recovery')review.recovery='unknown';state.scenario=s;state.emptyHistory=s==='empty';state.drawer=false;state.running=s==='working';state.settings=s==='settings';state.settingsTab='layout';state.tool='';state.inspector=s==='changes'?'changes':s==='recovery'?'history':'plan';state.detailsOpen=['changes','recovery','queue'].includes(s);state.decision='pending';state.notice='';if(s==='file')state.mode='ide';render();if(state.settings)document.getElementById('settings-title').focus()}
window.prototype={resetLayout:()=>{layout={...layoutDefaults};persistLayout();applyLayout();},setMode:m=>{state.mode=m;render()},setScenario,reset:()=>{review=reviewDefaults();state={mode:'ide',scenario:'ready',sidebar:true,context:true,drawer:false,search:'',selected:'TaskPanel.tsx',draft:initialCode,saved:initialCode,tool:'',inspector:'plan',decision:'pending',sideView:'files',projectQuery:'',memory:'Сохранять текущую компоновку и показывать реальные результаты проверок.',settingsTab:'layout',detailsOpen:false,model:'Neutral Demo',settingsQuery:'',messages:[],prompt:'',emptyHistory:false,running:false,settings:false,side:'right',notice:'',session:'Подготовить панель задач'};render()}};
document.addEventListener('keydown',e=>{if(state.settings&&e.key==='Tab'){const f=[...document.querySelectorAll('.dialog button:not([disabled]),.dialog input,.dialog select,.dialog [role=separator]')];if(!f.length)return;const i=f.indexOf(document.activeElement);if(e.shiftKey&&(i<=0)){e.preventDefault();f[f.length-1].focus()}else if(!e.shiftKey&&(i===f.length-1||i<0)){e.preventDefault();f[0].focus()}return}if(state.settings){if(e.key==='Escape'){e.preventDefault();action('close-settings')}return}if(e.key==='Escape'&&state.detailsOpen){e.preventDefault();action('toggle-details');return}if(document.activeElement?.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();action(state.mode==='ide'?'mode-chat':'mode-ide');document.querySelector('[role=tab][aria-selected=true]').focus();return}if(e.ctrlKey&&e.key.toLowerCase()==='b'){e.preventDefault();action('toggle-sidebar')}else if(e.ctrlKey&&e.key.toLowerCase()==='j'){e.preventDefault();action('toggle-context')}else if(e.ctrlKey&&e.key.toLowerCase()==='s'&&state.mode==='ide'&&state.selected==='TaskPanel.tsx'){e.preventDefault();action('save-file')}});
render();

